package com.bank.lazy;

import java.util.*;
import java.util.logging.*;

public class LazyDemo {
    private static final Logger log = Logger.getLogger("Lazy");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        LazyService service = new LazyService();
        service.noTerminal();   // map never runs → nothing logged from the lambda
        log.info(() -> "with terminal: " + service.withTerminal());
    }
}

// ─── Would be in service/LazyService.java ───
class LazyService {
    // no terminal → pipeline built but NOT executed
    void noTerminal() {
        java.util.stream.Stream<Integer> pipeline =
            java.util.stream.Stream.of(1, 2, 3)
                .map(i -> {
                    System.out.println("  doubling " + i);  // NEVER printed — lazy!
                    return i * 2;
                });
        // pipeline is a configured Stream; map has not run
    }

    // terminal triggers execution
    List<Integer> withTerminal() {
        return java.util.stream.Stream.of(1, 2, 3)
            .map(i -> i * 2)
            .toList();   // terminal → now map runs
    }
}
